# -*- coding: utf-8 -*-
import json
R='src/data/readings.json'; S='src/data/staffStudy.json'
readings=json.load(open(R,encoding='utf-8')); staff=json.load(open(S,encoding='utf-8'))
rid={r['id'] for r in readings}; sid={s['id'] for s in staff}

pop=("במהלך החודש השני שלי בקולג', המרצה שלנו ערך לנו בוחן פתע. קיבלתי את המבחן, ועברתי מהר על כל השאלות. עיניי נתקעו בשאלה האחרונה: \"מהו שמה הפרטי של המנקה?\". זאת סוג של בדיחה. ראיתי את המנקה הרבה פעמים. היא היתה גבוהה, שחורת שיער, בערך בשנות ה-30 לחייה, אבל למה שאדע את שמה? הגשתי את הבוחן והשארתי את השאלה האחרונה ללא מענה. רגע לפני שהכיתה התרוקנה, שאל אחד הסטודנטים את המרצה אם השאלה האחרונה תכנס לציון של הבוחן.\n"
"\"בוודאי\" ענה המרצה. \"בקריירה שלך, אתה תפגוש המון אנשים. כולם חשובים. הם ראויים לייחס והדאגה שלך, אפילו אם כל מה שתעשה זה לחייך אליהם ולהגיד 'שלום'\".\n"
"לעולם לא שכחתי את השיעור הזה. גם למדתי את השם שלה, קראו לה דורותי.")

stone=("היה היה מלך, שבאחד הימים החליט לבחון את אופי נתיניו. לשם כך, הוא הניח באמצע אחת הדרכים בממלכה, אבן גדולה. הוא התחבא מאחורי סלע וצפה במעשי נתיניו אשר נתקלו באבן בדרכם. כמה מאצילי הממלכה וכן הסוחרים העשירים שבה, עברו ליד האבן, התעלמו ממנה והמשיכו בדרכם.\n"
"המלך המאוכזב המשיך לצפות בעוברים ושבים, שלא רק שלא הזיזו את האבן מהדרך, אלא אף הגדילו לעשות והאשימו את המלך שאינו דואג לניקיון ופינוי שבילי הממלכה.\n"
"לבסוף, כשהיה המלך כמעט על סף ייאוש מנתיניו האנוכיים, חלף איכר כשהוא נושא בידיו שקים המכילים ירקות. ברגע שהבחין באבן הגדולה, הניח האיכר את שקיו הכבדים וניסה להזיז את האבן לצד הדרך. לאחר מאמצים רבים וממושכים, הוא הצליח במשימה!\n"
"להפתעתו, מצא האיכר מתחת לאבן הכבדה ארנק, שהכיל מטבעות זהב רבים וכן מכתב מהמלך בו נאמר, כי הזהב מיועד למי שיזיז את האבן הטורדנית מהשביל.\n"
"האיכר הבין מה שרבים אחרים לא השכילו להבין: כל מכשול בדרכך הוא הזדמנות שיכולה לשפר את מצבך. לא תמיד צריך לעקוף מכשולים. עם מכשולים יש להתמודד! ללמוד מהם ולהמשיך הלאה... נסו זאת, ואולי גם אתם תמצאו שק זהב שמחכה רק לכם...")

morning=("קבוצה של שוחטים מישראל יצאה לביקור עבודה בארצות הברית. כידוע בתי המטבחיים הגדולים נמצאים שם בגלל האפשרויות הגדולות לגידול בקר בקנה מידה נרחב. בבתי המטבחיים שם שוחטים אלפי ראשי בקר ביום, ומייצאים את הבשר לכל העולם.\n"
"קבוצה של כ–30 שוחטים מישראל נסעה לשם לשבוע של עבודה מרוכזת, בו הם אמורים לעבוד בשחיטה מן הבוקר עד הערב, ומה שיוצא תחת ידם מקבל תו תקן מיוחד של כשרות מהודרת.\n"
"השחיטה מתבצעת בחדרי קירור מיוחדים, שם הכל עובד בשיטת הסרט הנע, ובצורה חשמלית הכל מועבר לניקוי ולאריזה. בגלל הקור הגדול בחדר הקירור נמצאים שם בלבוש חם ואי אפשר להישאר שם זמן רב. מדי כמה זמן צריך לצאת להתחמם בחדר סמוך ולחזור לעבודה.\n"
"בתום יום עבודה אחד כשסיימו השוחטים את מלאכתם ויצאו מן הבניין לכיוון מקום לינתם, פנה אליהם השומר הכושי שעמד בכניסה ושאל אותם: \"לא חסר לכם מישהו?\".\n"
"הם בדקו, ומייד התברר שמישהו חסר. הם חזרו מהר חזרה פנימה ומצאו את אחד מחבריהם שנשכח בטעות בתוך חדר הקירור וננעל שם. הם מצאו אותו שניות ספורות לפני שנפח את נשמתו מן הקור. רק בזכות ערנותו של השומר הכושי ניצלו חייו.\n"
"לאחר מכן שאלו את השומר: \"הרי מאות אנשים עוברים על פניך מדי יום. איך זה שדווקא אותו זכרת ושמת לב שהוא חסר?\". \"הוא היחיד שאמר לי בוקר טוב\", ענה השומר.")

mouse=("עכבר הציץ דרך חריץ בקיר וראה את האיכר ואשתו פותחים חבילה.\n"
"\"מעניין איזה מזון יש בחבילה\" חשב לעצמו, אך הזדעזע לראות את הזוג מוציא מלכודת עכברים מן הקופסא.\n"
"הוא יצא אל החצר וזעק אזהרה: \"יש מלכודת עכברים בבית! יש מלכודת עכברים בבית!\"\n"
"התרנגולת קרקרה וזקפה אליו את ראשה: \"אדון עכבר, אני יודעת שזה אסון לגביך, אבל אין לכך שום משמעות בשבילי\".\n"
"העכבר פנה אל החזיר: \"יש מלכודת עכברים בבית!\"\n"
"החזיר הפגין סימפטיה ואמר: \"אני כל כך מצטער, מר עכבר, אבל אין שום דבר שאני יכול לעשות חוץ מלהתפלל לשלומך\".\n"
"העכבר פנה אל הפרה וזו הגיבה בזלזול: \"אפשר לחשוב - מלכודת עכברים. אני ממש בסכנה, אה...\"\n"
"עצוב ומפוחד חזר העכבר אל הבית, להתמודד לבדו עם מלכודת העכברים.\n"
"בלילה נשמע קול פצפוץ, כזה שמשמיעה מלכודת עכברים שהופעלה. אשת האיכר קפצה ממיטתה לראות מה לכדה המלכודת. בחושך לא ראתה כי היה זה נחש ארסי שזנבו נתפס במכשיר. הנחש הכיש את האישה והיא הובהלה לבית החולים. היא טופלה וחזרה לביתה סובלת מחום גבוה.\n"
"כולם יודעים שהטיפול הטוב ביותר לחום גבוה הוא מרק עוף טרי. לכן לקח האיכר גרזן ושחט את התרנגולת כדי לבשל מרק.\n"
"שכנים וידידים באו לבקר את החולה וישבו לצידה מסביב לשעון. כדי להאכיל אותם, נאלץ האיכר לשחוט את החזיר.\n"
"האישה גססה עד שלבסוף נפטרה. מכרים רבים באו ללוויה וכדי לסעוד אותם, שחט האיכר את הפרה.")

nguyen=("נוג'יוואן הזמין את חבריו לסעודת בשר דשנה. בעודו מבשל, הבחין כי אזל המלח. קרא נוג'יוואן לבנו, וביקשו לצאת לשוק לקנות מעט מלח: \"שים לב כי משלם אתה את המחיר ההוגן, לא יותר מדי ולא פחות מדי.\"\n"
"\"אני מבין למה לא יותר מדי, אבי, אך אם יעלה בידי לעמוד על המיקח, מדוע לא אחסוך כסף?\"\n"
"\"כך אפשר אולי לנהוג בעיר הגדולה, אולם בכפר קטן כשלנו, עלול מעשה שכזה להביא לחורבן.\" אמר נוג'יוואן והסביר: \"מי שמוכר מלח במחיר מופחת, הרי שהוא זקוק נואשות לכסף. מי שמנצל זאת, נוהג בחוסר כבוד כלפי אדם שעבד קשה מאוד על מנת להשיג דבר מה.\"\n"
"\"אבל חוסר כבוד לאדם אחד, אין בו כדי להביא לחורבנו של כפר שלם\", אמר הבן. ענה נוג'יוואן: \"ייתכן, אבל חורבן מתחיל תמיד במעשה לא הוגן אחד, שמישהו חשב כי אין לו משמעות.\"")

bus=("שעת לילה מאוחרת. ברק הלך במהירות ברחוב החשוך, מפחד לפספס את האוטובוס האחרון הביתה. הוא לא ידע איך יבלה כאן את הלילה אם יפסידהו. כשחצה את הסמטה ראה אדם על כסא גלגלים.\n"
"האיש פנה אליו: \"סליחה, אדוני, אתה יכול לקחת אותי לתחנה של אוטובוס 45?\".\n"
"ברק הציץ בשעונו. יש לו עוד חצי דקה. הוא התלבט לשניה אך גם ידע שלא יוכל לנהוג אחרת. הוא החל מסיע את האיש, עד שראה מרחוק את האוטובוס מגיע לתחנה.\n"
"\"רוץ אחריו\" אמר האיש. ברק עזב את האיש ורץ אחרי האוטובוס. כשהגיע מתנשף, אמר לנהג: \"בבקשה, חכה עוד רגע! יש פה עוד מישהו על כסא גלגלים שצריך לעלות\".\n"
"הנהג המשופם הסתכל על ברק ואמר בכעס: \"איני מחכה לאף אחד. אתה רוצה לעלות?\".\n"
"ברק הסתכל באיש שנותר רחוק וסימן לו לעלות: \"לא, אני לא עולה בלעדיו\".\n"
"הנהג לא חשב פעמיים, סגר את הדלת והמשיך לנסוע. ברק לא ידע מה לעשות. הוא חזר אל האיש וטייל עמו מעט בקרבת התחנה. לפתע, הלא יאמן קרה. אוטובוס נוסף הופיע בקצה הרחוב.\n"
"\"בחורים, אתם רוצים לעלות?\", אמר הנהג.\n"
"\"כמובן\" שמח ברק. \"חשבתי שהאוטובוס הקודם היה האחרון\".\n"
"\"גם אני חשבתי כך, עד שראיתי אתכם מחלון ביתי\" אמר הנהג. \"והבנתי שהוא לא האוטובוס האחרון. אחריו אני בא - באוטובוס המהיר - לאסוף את אלה שאכפת להם...\".")

def R_(id,title,age,mn,mx,desc,text,how,tags):
    return dict(id=id,title=title,domain='ערכי',ageLabel=age,ageMin=mn,ageMax=mx,description=desc,text=text,howToUse=how,source='אנונימי',tags=tags)
new_r=[
 R_('surprise-quiz-cleaner','בוחן פתע',"כיתה ח'-י\"ב",8,12,'שאלה אחרונה בבוחן פתע שלא היו אמורים לדעת, והמרצה שמסביר למה היא חשובה.',pop,'לקרוא בקול ולשאול: את מי ״לא רואים״ אצלנו בסניף?',['אכפתיות','הערכה','לראות את האדם']),
 R_('the-big-stone','האבן הגדולה',"כיתה ו'-י\"ב",6,12,'מלך מניח אבן בדרך ובודק מי יזיז אותה.',stone,'לשאול: מי ״מזיז אבנים״ אצלנו ואיפה אנחנו עוקפים?',['אכפתיות','אחריות','משל']),
 R_('only-one-who-said-good-morning','היחיד שאמר בוקר טוב',"כיתה ח'-י\"ב",8,12,'שומר בכניסה שם לב דווקא לאדם אחד שחסר.',morning,'לקרוא בקול. שימו לב: בנוסח המקורי מופיע הכינוי ״הכושי״; כדאי להחליט מראש אם לקרוא כך או לומר ״השומר״.',['אכפתיות','לראות את האדם','בוקר טוב']),
 R_('mousetrap','מלכודת עכברים',"כיתה ה'-י\"ב",5,12,'עכבר מזהיר את חיות החצר, ואף אחת לא מתייחסת.',mouse,'לשאול: מתי אמרנו ״זה לא נוגע לי״ ומה קרה אחרי זה.',['אכפתיות','ערבות הדדית','משל']),
 R_('nguyen-salt','העצה של ניג׳יוואן',"כיתה ט'-י\"ב",9,12,'אב מסביר לבנו למה לא מתמקחים על המחיר מול מי שזקוק לכסף.',nguyen,'לשאול: איפה אצלנו ״חוסר הגינות קטן״ שנראה שאין לו משמעות?',['אכפתיות','יושר','משל']),
 R_('those-who-care-bus','אלה שאכפת להם',"כיתה ו'-י\"ב",6,12,'ברק מוותר על האוטובוס האחרון כדי לעזור לאדם על כסא גלגלים, ומגיע אוטובוס נוסף.',bus,'לשאול: מה ברק ויתר עליו, ומה קיבל?',['אכפתיות','עזרה','סיפור']),
]
readings += [r for r in new_r if r['id'] not in rid]

staff_new=[
 dict(id='staff-care-seeing-the-person',title='אכפתיות: לראות את האדם',topic='אכפתיות',duration=35,forWhom='כל צוות ההדרכה',
  description='שני סיפורים קצרים על אנשים שרואים אחרים, ושאלה אחת: את מי ״לא רואים״ אצלנו.',
  goals=['הצוות יזהה חניך או חבר צוות שאנחנו נוטים לא להבחין בו','כל מדריך יבחר פעולה קטנה אחת של תשומת לב לאדם מסוים'],
  opening='שואלים בסבב: ״מי אמר לכם בפעם האחרונה שלום בחום, ומה זה עשה לכם?״',
  content=("קוראים בקול את שני הסיפורים.\n\nא. בוחן פתע\n\n"+pop+"\n\nב. היחיד שאמר בוקר טוב\n\n"+morning+"\n\n"
   "סיפור נוסף, בתקציר במילים שלנו: אב מטייל עם בתו בת הארבע בירושלים, והיא מבקשת שקל ״לתת לבוריס״. מתברר שבוריס הוא נגן ברחוב, ושהיא זוכרת את שמו מפעם קודמת. הנגן נדהם שזכרה, ומחזיר לה את השקל ואומר שבשבילה הוא מנגן חינם. "
   "המסקנה בסוף הסיפור: דברים שנראים לאדם אחד קטנים, כמו לזכור שם או לומר בוקר טוב, שווים לאדם אחר עולם ומלואו."),
  discussion=['למי בסניף שלנו אף אחד לא זוכר את השם, או לא מברך בבוקר טוב?','מה מונע מאיתנו לשים לב, ומה היה עוזר?','מה אפשר לעשות כצוות כדי שאף אחד לא יהיה ״השומר שאף אחד לא רואה״?'],
  takeaway='כל מדריך בוחר אדם אחד שישים לב אליו השבוע, ואומר את שמו בקול בסיום המפגש.'),
 dict(id='staff-care-when-it-isnt-mine',title='אכפתיות: כשזה לא נוגע לי',topic='אכפתיות',duration=40,forWhom='כל צוות ההדרכה',
  description='מלכודת עכברים ועצה של אב לבנו: מתי ״זה לא בעיה שלי״ הופך לבעיה של כולם.',
  goals=['הצוות יבין איך התעלמות מבעיה של אחר חוזרת אלינו','כל מדריך יבחר מקרה אחד שבו הוא רוצה להפסיק להתעלם'],
  opening='שואלים: ״מתי אמרתם לעצמכם ׳זה לא נוגע לי׳, ואחר כך הבנתם שכן?״',
  content=("קוראים בקול את שני הסיפורים.\n\nא. מלכודת עכברים\n\n"+mouse+"\n\nב. העצה של ניג׳יוואן\n\n"+nguyen+"\n\n"
   "בתקציר במילים שלנו: מרטין נימלר, כומר גרמני, כתב קטע מפורסם על כך שהנאצים באו אחד אחרי השני לקחת קבוצות שונות, והוא לא התנגד כי לא היה שייך אליהן. "
   "כשבאו לקחת אותו, כבר לא נותר מי שיתנגד. אפשר לחפש את הנוסח המלא בנוסחים שפורסמו בעקבות הקטע."),
  discussion=['מה הכי קשה לנו בלהגיד משהו כשזה לא נוגע לנו ישירות?','איזה ״חוסר הגינות קטן״ נראה לנו שאין לו משמעות, ומה אפשר לעשות?','מי אצלנו מוזהר ולא מקשיבים לו?'],
  takeaway='כל מדריך כותב משפט על דבר אחד שהוא ״לא ישאיר״ למישהו אחר השבוע.'),
]
staff += [s for s in staff_new if s['id'] not in sid]
json.dump(readings,open(R,'w',encoding='utf-8'),ensure_ascii=False,indent=2)
json.dump(staff,open(S,'w',encoding='utf-8'),ensure_ascii=False,indent=2)
print(len(readings),len(staff))
